changeSet.sql:
UPDATE achievement_definitions
SET is_active = false
WHERE key IN ('tournament_third', 'open_play_leader');

changeSet.rollback:
UPDATE achievement_definitions
SET is_active = true
WHERE key IN ('tournament_third', 'open_play_leader');

changeSet.sql:
CREATE INDEX IF NOT EXISTS idx_notifications_read_at_expiry
    ON notifications (read_at)
    WHERE read_at IS NOT NULL;

CREATE INDEX IF NOT EXISTS idx_notifications_unread_expiry
    ON notifications (created_at)
    WHERE read_at IS NULL;

ALTER TABLE notification_deliveries
    DROP CONSTRAINT IF EXISTS fk_notification_deliveries_notification;
ALTER TABLE notification_deliveries
    ADD CONSTRAINT fk_notification_deliveries_notification
    FOREIGN KEY (notification_id) REFERENCES notifications(id) ON DELETE CASCADE;

changeSet.rollback:
ALTER TABLE notification_deliveries
    DROP CONSTRAINT IF EXISTS fk_notification_deliveries_notification;
ALTER TABLE notification_deliveries
    ADD CONSTRAINT fk_notification_deliveries_notification
    FOREIGN KEY (notification_id) REFERENCES notifications(id);
